// The web build of Sudoku.
//
// Nothing here is a second implementation of the game: the board is generated by
// the same `SudokuEngine` the app uses, and the conflict test is the same rule.
// This file only carries that engine's answers across to JavaScript, so the page
// can be plain HTML and CSS instead of a 17 MB canvas app.
//
//   dart compile js -O2 web/games/sudoku.dart -o docs/js/sudoku.js
//
// It talks JSON strings both ways: no dart:js_interop objects are built by hand,
// so a change on either side cannot silently disagree about a field.
import 'dart:convert';
import 'dart:js_interop';
import 'dart:js_interop_unsafe';

import 'package:puzzle/ui/features/games/sudoku/sudoku_engine.dart';

void main() {
  globalContext.setProperty('sudokuNew'.toJS, _newBoard.toJS);
  globalContext.setProperty('sudokuConflicts'.toJS, _conflicts.toJS);
}

/// A fresh board: `{given: int[81], solution: int[81]}`, row-major, 0 = empty.
JSString _newBoard(JSNumber clues) {
  final solved = SudokuEngine.generateFullBoard();
  final puzzle = SudokuEngine.generateInitialPuzzle({
    'solved': solved,
    'clues': clues.toDartInt.clamp(28, 50),
  });
  return jsonEncode({
    'given': puzzle.expand((row) => row).toList(),
    'solution': solved.expand((row) => row).toList(),
  }).toJS;
}

/// Indices that repeat a number in their row, column or box.
JSString _conflicts(JSString flat) {
  final cells = (jsonDecode(flat.toDart) as List).cast<int>();
  final bad = <int>{};

  void mark(List<int> group) {
    final seen = <int, List<int>>{};
    for (final index in group) {
      final value = cells[index];
      if (value == 0) continue;
      (seen[value] ??= <int>[]).add(index);
    }
    for (final same in seen.values) {
      if (same.length > 1) bad.addAll(same);
    }
  }

  for (var line = 0; line < 9; line++) {
    mark([for (var i = 0; i < 9; i++) line * 9 + i]);
    mark([for (var i = 0; i < 9; i++) i * 9 + line]);
    final boxRow = (line ~/ 3) * 3;
    final boxCol = (line % 3) * 3;
    mark([
      for (var r = 0; r < 3; r++)
        for (var c = 0; c < 3; c++) (boxRow + r) * 9 + boxCol + c,
    ]);
  }
  return jsonEncode(bad.toList()..sort()).toJS;
}
